INSERT INTO `natives_weapons` (`id`, `model`, `group`, `ammoType`, `displayName`, `description`, `createdAt`, `updatedAt`) VALUES
(1, 'dagger', 'melee', 'none', 'Antique Cavalry Dagger', 'You\'ve been rocking the pirate-chic look for a while, but no vicious weapon to complete the look? Get this dagger with a guarded hilt.', NULL, NULL),
(2, 'bat', 'melee', 'none', 'Baseball Bat', 'Aluminum baseball bat with leather grip. Lightweight yet powerful for all you big hitters out there.', NULL, NULL),
(3, 'bottle', 'melee', 'none', 'Broken Bottle', 'It\'s not clever and it\'s not pretty but, most of the time, neither is the guy coming at you with a knife. When all else fails, this gets the job done.', NULL, NULL),
(4, 'crowbar', 'melee', 'none', 'Crowbar', 'Heavy-duty crowbar forged from high quality, tempered steel for that extra leverage you need to get the job done.', NULL, NULL),
(5, 'flashlight', 'melee', 'none', 'Flashlight', 'Intensify your fear of the dark with this short range, battery-powered light source. Handy for blunt force trauma.', NULL, NULL),
(6, 'unarmed', 'melee', 'none', 'Fist', '', NULL, NULL),
(7, 'golfclub', 'melee', 'none', 'Golf Club', 'Standard length, mid iron golf club with rubber grip for a lethal short game.', NULL, NULL),
(8, 'hammer', 'melee', 'none', 'Hammer', 'A robust, multi-purpose hammer with wooden handle and curved claw, this old classic still nails the competition.', NULL, NULL),
(9, 'hatchet', 'melee', 'none', 'Hatchet', 'Make kindling... of your pals with this easy to wield, easy to hide hatchet.', NULL, NULL),
(10, 'knuckle', 'melee', 'none', 'Brass Knuckles', 'Perfect for knocking out gold teeth, or as a gift to the trophy partner who has everything.', NULL, NULL),
(11, 'knife', 'melee', 'none', 'Knife', 'This carbon steel 7\" bladed knife is dual edged with a serrated spine to provide improved stabbing and thrusting capabilities.', NULL, NULL),
(12, 'machete', 'melee', 'none', 'Machete', 'America\'s West African arms trade isn\'t just about giving. Rediscover the simple life with this rusty cleaver.', NULL, NULL),
(13, 'switchblade', 'melee', 'none', 'Switchblade', 'From your pocket to hilt-deep in the other guy\'s ribs in under a second: folding knives will never go out of style.', NULL, NULL),
(14, 'nightstick', 'melee', 'none', 'Nightstick', '24\" polycarbonated side-handled nightstick.', NULL, NULL),
(15, 'wrench', 'melee', 'none', 'Pipe Wrench', 'Perennial favourite of apocalyptic survivalists and violent fathers the world over, apparently it also doubles as some kind of tool.', NULL, NULL),
(16, 'battleaxe', 'melee', 'none', 'Battle Axe', 'If it\'s good enough for medieval foot soldiers, modern border guards and pushy soccer moms, it\'s good enough for you.', NULL, NULL),
(17, 'poolcue', 'melee', 'none', 'Pool Cue', 'Ah, there\'s no sound as satisfying as the crack of a perfect break, especially when it\'s the other guy\'s spine.', NULL, NULL),
(18, 'stone_hatchet', 'melee', 'none', 'Stone Hatchet', 'There\'s retro, there\'s vintage, and there\'s this. After 500 years of technological development and spiritual apocalypse, pre-Colombian chic is back.', NULL, NULL),
(19, 'pistol', 'pistol', 'pistol', 'Pistol', 'Standard handgun. A .45 caliber combat pistol with a magazine capacity of 12 rounds that can be extended to 16.', NULL, NULL),
(20, 'pistol_mk2', 'pistol', 'pistol', 'Pistol Mk II', 'Balance, simplicity, precision: nothing keeps the peace like an extended barrel in the other guy\'s mouth.', NULL, NULL),
(21, 'combatpistol', 'pistol', 'pistol', 'Combat Pistol', 'A compact, lightweight, semi-automatic pistol designed for law enforcement and personal defense. 12-round magazine with option to extend to 16 rounds.', NULL, NULL),
(22, 'appistol', 'pistol', 'pistol', 'AP Pistol', 'High-penetration, fully-automatic pistol. Holds 18 rounds in magazine with option to extend to 36 rounds.', NULL, NULL),
(23, 'stungun', 'stungun', 'stungun', 'Stun Gun', 'Fires a projectile that administers a voltage capable of temporarily stunning an assailant. Takes approximately 4 seconds to recharge after firing.', NULL, NULL),
(24, 'pistol50', 'pistol', 'pistol', 'Pistol .50', 'High-impact pistol that delivers immense power but with extremely strong recoil. Holds 9 rounds in magazine.', NULL, NULL),
(25, 'snspistol', 'pistol', 'pistol', 'SNS Pistol', 'Like condoms or hairspray, this fits in your pocket for a night out in a Vinewood club. It\'s half as accurate as a champagne cork but twice as deadly. Part of the Beach Bum Pack.', NULL, NULL),
(26, 'snspistol_mk2', 'pistol', 'pistol', 'SNS Pistol Mk II', 'The ultimate purse-filler: if you want to make Saturday Night really special, this is your ticket.', NULL, NULL),
(27, 'heavypistol', 'pistol', 'pistol', 'Heavy Pistol', 'The heavyweight champion of the magazine fed, semi-automatic handgun world. Delivers a serious forearm workout every time.', NULL, NULL),
(28, 'vintagepistol', 'pistol', 'pistol', 'Vintage Pistol', 'What you really need is a more recognizable gun. Stand out from the crowd at an armed robbery with this engraved pistol.', NULL, NULL),
(29, 'flaregun', 'pistol', 'pistol', 'Flare Gun', 'Use to signal distress or drunken excitement. Warning: pointing directly at individuals may cause spontaneous combustion.', NULL, NULL),
(30, 'marksmanpistol', 'pistol', 'pistol', 'Marksman Pistol', 'Not for the risk averse. Make it count as you\'ll be reloading as much as you shoot.', NULL, NULL),
(31, 'revolver', 'pistol', 'pistol', 'Heavy Revolver', 'A handgun with enough stopping power to drop a crazed rhino, and heavy enough to beat it to death if you\'re out of ammo.', NULL, NULL),
(32, 'revolver_mk2', 'pistol', 'pistol', 'Heavy Revolver Mk II', 'If you can lift it, this is the closest you\'ll get to shooting someone with a freight train.', NULL, NULL),
(33, 'doubleaction', 'pistol', 'pistol', 'Double Action Revolver', 'Ever been on the wrong side of the Micro SMG\'s big bad brother? Trust us, with double the capacity for conflict resolution, you\'d know.', NULL, NULL),
(34, 'raypistol', 'pistol', 'pistol', 'Up-n-Atomizer', 'Republican Space Ranger Special, fresh from the galactic war on socialism: no ammo, no mag, just one brutal energy pulse after another.', NULL, NULL),
(35, 'ceramicpistol', 'pistol', 'pistol', 'Ceramic Pistol', 'Not your grandma\'s ceramics. Although this pint-sized pistol is small enough to fit into her purse and won\'t set off a metal detector.', NULL, NULL),
(36, 'navyrevolver', 'pistol', 'pistol', 'Navy Revolver', 'A true museum piece. You want to know how the West was won - slow reload speeds and a whole heap of bloodshed.', NULL, NULL),
(37, 'gadgetpistol', 'pistol', 'pistol', 'Perico Pistol', 'A deadly shot. Don\'t be precious. You won\'t scuff the titanium nitride finish.', NULL, NULL),
(38, 'stungun_mp', 'stungun', 'stungun', 'Stun Gun', 'It\'s, like, literally stunning.', NULL, NULL),
(39, 'microsmg', 'smg', 'smg', 'Micro SMG', 'Combines compact design with a high rate of fire at approximately 700-900 rounds per minute.', NULL, NULL),
(40, 'smg', 'smg', 'smg', 'SMG', 'This is known as a good all-round submachine gun. Lightweight with an accurate sight and 30-round magazine capacity.', NULL, NULL),
(41, 'smg_mk2', 'smg', 'smg', 'SMG Mk II', 'Lightweight, compact, with a rate of fire to die very messily for: turn any confined space into a kill box at the click of a well-oiled trigger.', NULL, NULL),
(42, 'assaultsmg', 'smg', 'smg', 'Assault SMG', 'A high-capacity submachine gun that is both compact and lightweight. Holds up to 30 bullets in one magazine.', NULL, NULL),
(43, 'combatpdw', 'smg', 'smg', 'Combat PDW', 'Who said personal weaponry couldn\'t be worthy of military personnel? Thanks to our lobbyists, not Congress. Integral suppressor.', NULL, NULL),
(44, 'machinepistol', 'smg', 'smg', 'Machine Pistol', 'This fully automatic is the snare drum to your twin-engine V8 bass: no drive-by sounds quite right without it.', NULL, NULL),
(45, 'minismg', 'smg', 'smg', 'Mini SMG', 'Increasingly popular since the marketing team looked beyond spec ops units and started caring about the little guys in low income areas.', NULL, NULL),
(46, 'raycarbine', 'mg', 'mg', 'Unholy Hellbringer', 'Republican Space Ranger Special. If you want to turn a little green man into little green goo, this is the only American way to do it.', NULL, NULL),
(47, 'pumpshotgun', 'shotgun', 'shotgun', 'Pump Shotgun', 'Standard shotgun ideal for short-range combat. A high-projectile spread makes up for its lower accuracy at long range.', NULL, NULL),
(48, 'pumpshotgun_mk2', 'shotgun', 'shotgun', 'Pump Shotgun Mk II', 'Only one thing pumps more than action than a pump action: watch out, the recoil is almost as deadly as the shot.', NULL, NULL),
(49, 'sawnoffshotgun', 'shotgun', 'shotgun', 'Sawed-Off Shotgun', 'This single-barrel, sawed-off shotgun compensates for its low range and ammo capacity with devastating efficiency in close combat.', NULL, NULL),
(50, 'assaultshotgun', 'shotgun', 'shotgun', 'Assault Shotgun', 'Fully automatic shotgun with 8 round magazine and high rate of fire.', NULL, NULL),
(51, 'bullpupshotgun', 'shotgun', 'shotgun', 'Bullpup Shotgun', 'More than makes up for its slow, pump-action rate of fire with its range and spread. Decimates anything in its projectile path.', NULL, NULL),
(52, 'musket', 'shotgun', 'shotgun', 'Musket', 'Armed with nothing but muskets and a superiority complex, the Brits took over half the world. Own the gun that built an Empire.', NULL, NULL),
(53, 'heavyshotgun', 'shotgun', 'shotgun', 'Heavy Shotgun', 'The weapon to reach for when you absolutely need to make a horrible mess of the room. Best used near easy-wipe surfaces only.', NULL, NULL),
(54, 'dbshotgun', 'shotgun', 'shotgun', 'Double Barrel Shotgun', 'Do one thing, do it well. Who needs a high fire rate when your first shot turns the other guy into a fine mist?', NULL, NULL),
(55, 'autoshotgun', 'shotgun', 'shotgun', 'Sweeper Shotgun', 'How many effective tools for riot control can you tuck into your pants? OK, two. But this is the other one.', NULL, NULL),
(56, 'combatshotgun', 'shotgun', 'shotgun', 'Combat Shotgun', 'There’s only one semi-automatic shotgun with a fire rate that sets the LSFD alarm bells ringing, and you’re looking at it.', NULL, NULL),
(57, 'assaultrifle', 'rifle', 'rifle', 'Assault Rifle', 'This standard assault rifle boasts a large capacity magazine and long distance accuracy.', NULL, NULL),
(58, 'assaultrifle_mk2', 'rifle', 'rifle', 'Assault Rifle Mk II', 'The definitive revision of an all-time classic: all it takes is a little work, and looks can kill after all.', NULL, NULL),
(59, 'carbinerifle', 'rifle', 'rifle', 'Carbine Rifle', 'This is bespoke, artisan firepower: you couldn\'t deliver a hail of bullets with more love and care if you inserted them by hand.', NULL, NULL),
(60, 'carbinerifle_mk2', 'rifle', 'rifle', 'Carbine Rifle Mk II', 'This is bespoke, artisan firepower: you couldn\'t deliver a hail of bullets with more love and care if you inserted them by hand.', NULL, NULL),
(61, 'advancedrifle', 'rifle', 'rifle', 'Advanced Rifle', 'The most lightweight and compact of all assault rifles, without compromising accuracy and rate of fire.', NULL, NULL),
(62, 'specialcarbine', 'rifle', 'rifle', 'Special Carbine', 'Combining accuracy, maneuverability and low recoil, this is an extremely versatile assault rifle for any combat situation.', NULL, NULL),
(63, 'specialcarbine_mk2', 'rifle', 'rifle', 'Special Carbine Mk II', 'The jack of all trades just got a serious upgrade: bow to the master.', NULL, NULL),
(64, 'bullpuprifle', 'rifle', 'rifle', 'Bullpup Rifle', 'The latest Chinese import taking America by storm, this rifle is known for its balanced handling. Lightweight and very controllable in automatic fire.', NULL, NULL),
(65, 'bullpuprifle_mk2', 'rifle', 'rifle', 'Bullpup Rifle Mk II', 'So precise, so exquisite, it\'s not so much a hail of bullets as a symphony.', NULL, NULL),
(66, 'compactrifle', 'rifle', 'rifle', 'Compact Rifle', 'Half the size, all the power, double the recoil: there\'s no riskier way to say \\\"I\'m compensating for something\\\".', NULL, NULL),
(67, 'militaryrifle', 'rifle', 'rifle', 'Military Rifle', 'This immensely powerful assault rifle was designed for highly qualified, exceptionally skilled soldiers. Yes, you can buy it.', NULL, NULL),
(68, 'heavyrifle', 'rifle', 'rifle', 'Heavy Rifle', 'The no-holds-barred 30-round answer to that eternal question, how do I get this guy off my back?', NULL, NULL),
(69, 'tacticalrifle', 'rifle', 'rifle', 'Service Carbine', 'This season\'s must-have hardware for law enforcement, military personnel and anyone locked in a fight to the death with either law enforcement or military personnel.', NULL, NULL),
(70, 'mg', 'mg', 'mg', 'MG', 'General purpose machine gun that combines rugged design with dependable performance. Long range penetrative power. Very effective against large groups.', NULL, NULL),
(71, 'combatmg', 'mg', 'mg', 'Combat MG', 'Lightweight, compact machine gun that combines excellent maneuverability with a high rate of fire to devastating effect.', NULL, NULL),
(72, 'combatmg_mk2', 'mg', 'mg', 'Combat MG Mk II', 'You can never have too much of a good thing: after all, if the first shot counts, then the next hundred or so must count for double.', NULL, NULL),
(73, 'gusenberg', 'mg', 'mg', 'Gusenberg Sweeper', 'Complete your look with a Prohibition gun. Looks great being fired from an Albany Roosevelt or paired with a pinstripe suit.', NULL, NULL),
(74, 'sniperrifle', 'sniper', 'sniper', 'Sniper Rifle', 'Standard sniper rifle. Ideal for situations that require accuracy at long range. Limitations include slow reload speed and very low rate of fire.', NULL, NULL),
(75, 'heavysniper', 'sniper', 'sniper', 'Heavy Sniper', 'Far away, yet always intimate: if you\'re looking for a secure foundation for that long-distance relationship, this is it.', NULL, NULL),
(76, 'heavysniper_mk2', 'sniper', 'sniper', 'Heavy Sniper Mk II', 'Far away, yet always intimate: if you\'re looking for a secure foundation for that long-distance relationship, this is it.', NULL, NULL),
(77, 'marksmanrifle', 'sniper', 'sniper', 'Marksman Rifle', 'Known in military circles as The Dislocator, this mod set will destroy both the target and your shoulder, in that order.', NULL, NULL),
(78, 'marksmanrifle_mk2', 'sniper', 'sniper', 'Marksman Rifle Mk II', 'Known in military circles as The Dislocator, this mod set will destroy both the target and your shoulder, in that order.', NULL, NULL),
(79, 'precisionrifle', 'sniper', 'sniper', 'Precision Rifle', 'A rifle for perfectionists. Because why settle for right-between-the-eyes, when you could have right-through-the-superior-frontal-gyrus?', NULL, NULL),
(80, 'rpg', 'heavy', 'rpg', 'RPG', 'A portable, shoulder-launched, anti-tank weapon that fires explosive warheads. Very effective for taking down vehicles or large groups of assailants.', NULL, NULL),
(81, 'grenadelauncher', 'heavy', 'grenadeLauncher', 'Grenade Launcher', 'A compact, lightweight grenade launcher with semi-automatic functionality. Holds up to 10 rounds.', NULL, NULL),
(82, 'grenadelauncher_smoke', 'heavy', 'grenadeLauncherSmoke', 'Tear Gas Launcher\n', '', NULL, NULL),
(83, 'minigun', 'heavy', 'minigun', 'Minigun', 'A devastating 6-barrel machine gun that features Gatling-style rotating barrels. Very high rate of fire (2000 to 6000 rounds per minute).', NULL, NULL),
(84, 'firework', 'heavy', 'firework', 'Firework Launcher', 'Put the flair back in flare with this firework launcher, guaranteed to raise some oohs and aahs from the crowd. Part of the Independence Day Special.', NULL, NULL),
(85, 'railgun', 'heavy', 'railgun', 'Railgun', 'All you need to know is - magnets, and it does horrible things to the things it\'s pointed at.', NULL, NULL),
(86, 'hominglauncher', 'heavy', 'homingLauncher', 'Homing Launcher', 'Infrared guided fire-and-forget missile launcher. For all your moving target needs.', NULL, NULL),
(87, 'compactlauncher', 'heavy', 'grenadeLauncher', 'Compact Grenade', 'Focus groups using the regular model suggested it was too accurate and found it awkward to use with one hand on the throttle. Easy fix.', NULL, NULL),
(88, 'rayminigun', 'heavy', 'minigun', 'Widowmaker', 'Republican Space Ranger Special. GO AHEAD, SAY I\'M COMPENSATING FOR SOMETHING. I DARE YOU.', NULL, NULL),
(89, 'emplauncher', 'heavy', 'empLauncher', 'Compact EMP Launcher', 'Ever seen a confetti cannon? The Compact EMP Launcher is just like that, but instead of paper and happiness, it\'s an electromagnetic pulse, short circuits and shattered dreams.', NULL, NULL),
(90, 'grenade', 'thrown', 'grenade', 'Grenade', 'Standard fragmentation grenade. Pull pin, throw, then find cover. Ideal for eliminating clustered assailants.', NULL, NULL),
(91, 'bzgas', 'thrown', 'bzgas', 'BZ Gas', '', NULL, NULL),
(92, 'molotov', 'thrown', 'molotov', 'Molotov Cocktail', 'Crude yet highly effective incendiary weapon. No happy hour with this cocktail.', NULL, NULL),
(93, 'stickybomb', 'thrown', 'stickyBomb', 'Sticky Bomb', 'A plastic explosive charge fitted with a remote detonator. Can be thrown and then detonated or attached to a vehicle then detonated.', NULL, NULL),
(94, 'proxmine', 'thrown', 'proxMine', 'Proximity Mines', 'Leave a present for your friends with these motion sensor landmines. Short delay after activation.', NULL, NULL),
(95, 'snowball', 'thrown', 'snowball', 'Snowballs', '', NULL, NULL),
(96, 'pipebomb', 'thrown', 'pipeBomb', 'Pipe Bombs', 'Remember, it doesn\'t count as an IED when you buy it in a store and use it in a first world country.', NULL, NULL),
(97, 'ball', 'thrown', 'ball', 'Baseball', '', NULL, NULL),
(98, 'smokegrenade', 'thrown', 'smokeGrenade', 'Tear Gas', 'Tear gas grenade, particularly effective at incapacitating multiple assailants. Sustained exposure can be lethal.\"', NULL, NULL),
(99, 'flare', 'thrown', 'flare', 'Flare', '', NULL, NULL),
(100, 'petrolcan', 'thrown', 'petrolCan', 'Jerry Can', 'Leaves a trail of gasoline that can be ignited.', NULL, NULL),
(101, 'parachute', 'thrown', 'parachute', 'Parachute', '', NULL, NULL),
(102, 'fireextinguisher', 'thrown', 'fireExtinguisher', 'Fire Extinguisher', '', NULL, NULL),
(103, 'hazardcan', 'thrown', 'hazardousCan', 'Hazardous Jerry Can', '', NULL, NULL),
(104, 'fertilizercan', 'thrown', 'fertilizerCan', 'Fertilizer Can', '', NULL, NULL),
(105, 'battlerifle', 'rifle', 'rifle', 'Battle Rifle', 'Does life feel like a daily battle? Then why not try the Battle Rifle: the fast-acting pick-me-up that flawlessly targets every pain in your ass.', NULL, NULL),
(106, 'snowlauncher', 'heavy', 'snowLauncher', 'Snowball Launcher', 'There\'s no greater gift than pummeling someone with rounds of festive cheer. With automatic reload, there\'s no time for anyone to disagree.', NULL, NULL),
(107, 'hackingdevice', 'thrown', 'hackingDevice', 'Hacking Device', '', NULL, NULL),
(108, 'tecpistol', 'smg', 'smg', 'Tactical SMG', 'Ever been on the wrong side of the Micro SMG\'s big bad brother? Trust us, with double the capacity for conflict resolution, you\'d know.', NULL, NULL),
(109, 'candycane', 'melee', 'none', 'Candy Cane', 'This year, why not go one step further? Add to the onslaught of music, lights, and merriment by literally beating your peers to death with the festive spirit.', NULL, NULL),
(112, 'pistolxm3', 'pistol', 'pistol', 'WM 29 Pistol\r\n', 'If you think shooting off without lifting a finger is a problem, there\'s a pill for that. But if you think it\'s a plus, there\'s the semi-automatic WM 29 Pistol', NULL, NULL),
(113, 'railgunxm3', 'heavy', 'railgunXM3', 'Railgun XM3', 'All you need to know is — magnets, and it does horrible things to the things it\'s pointed at.', NULL, NULL),
(114, 'acidpackage', 'thrown', 'acidPackage', 'Acid Package', '', NULL, NULL);
